-- ============================================================================
--  BASE DE DONNEES UNIVERSITE - Script Oracle (SQL Developer)
--  Projet BDA : 9 tables, 12 cles etrangeres, ~8 400 lignes
--
--  UTILISATION :
--    1. Connectez-vous a votre schema dans SQL Developer.
--    2. Ouvrez ce fichier (File > Open) puis cliquez sur "Run Script" (F5).
--       Attention : F5 (Run Script) et non Ctrl+Entree.
--    3. A la fin, le tableau de verification affiche le nombre de lignes par table.
--
--  Le script est re-executable : il supprime d'abord les tables existantes.
--  Note : la colonne "session" des notes est renommee "session_exam" car
--         SESSION est un mot reserve dans Oracle.
-- ============================================================================

SET DEFINE OFF
SET SQLBLANKLINES ON
SET FEEDBACK OFF
SET ECHO OFF

-- ----------------------------------------------------------------------------
-- (Optionnel) Creer un utilisateur dedie - a executer en SYSTEM / SYS puis
-- vous reconnecter avec ce nouvel utilisateur. Decommentez si besoin.
-- ----------------------------------------------------------------------------
-- CREATE USER univ IDENTIFIED BY univ123 QUOTA UNLIMITED ON USERS;
-- GRANT CONNECT, RESOURCE, CREATE VIEW, CREATE TRIGGER, CREATE PROCEDURE TO univ;

-- ----------------------------------------------------------------------------
-- 1. SUPPRESSION DES TABLES EXISTANTES (ordre inverse des dependances)
-- ----------------------------------------------------------------------------
BEGIN
  FOR t IN (SELECT column_value AS cmd FROM TABLE(sys.odcivarchar2list(
              'DROP VIEW v_releve',
              'DROP TABLE absences CASCADE CONSTRAINTS PURGE',
              'DROP TABLE notes CASCADE CONSTRAINTS PURGE',
              'DROP TABLE seances CASCADE CONSTRAINTS PURGE',
              'DROP TABLE modules CASCADE CONSTRAINTS PURGE',
              'DROP TABLE etudiants CASCADE CONSTRAINTS PURGE',
              'DROP TABLE salles CASCADE CONSTRAINTS PURGE',
              'DROP TABLE enseignants CASCADE CONSTRAINTS PURGE',
              'DROP TABLE filieres CASCADE CONSTRAINTS PURGE',
              'DROP TABLE departements CASCADE CONSTRAINTS PURGE'))) LOOP
    BEGIN
      EXECUTE IMMEDIATE t.cmd;
    EXCEPTION
      WHEN OTHERS THEN
        IF SQLCODE != -942 THEN RAISE; END IF;   -- -942 : objet inexistant, on ignore
    END;
  END LOOP;
END;
/

-- ----------------------------------------------------------------------------
-- (Optionnel) NETTOYAGE TOTAL : supprime TOUTES les tables de votre schema,
-- meme celles qui ne font pas partie de ce projet. Decommentez uniquement si
-- vous voulez repartir d'un schema completement vide.
-- ----------------------------------------------------------------------------
-- BEGIN
--   FOR v IN (SELECT view_name FROM user_views) LOOP
--     EXECUTE IMMEDIATE 'DROP VIEW "' || v.view_name || '"';
--   END LOOP;
--   FOR t IN (SELECT table_name FROM user_tables) LOOP
--     EXECUTE IMMEDIATE 'DROP TABLE "' || t.table_name || '" CASCADE CONSTRAINTS PURGE';
--   END LOOP;
-- END;
-- /

-- ----------------------------------------------------------------------------
-- 2. CREATION DES TABLES
-- ----------------------------------------------------------------------------
CREATE TABLE departements (
    id_departement   NUMBER(4)     CONSTRAINT pk_departements PRIMARY KEY,
    nom_departement  VARCHAR2(60)  NOT NULL CONSTRAINT uq_dep_nom UNIQUE,
    batiment         VARCHAR2(30)  NOT NULL
);

CREATE TABLE filieres (
    id_filiere       NUMBER(4)     CONSTRAINT pk_filieres PRIMARY KEY,
    nom_filiere      VARCHAR2(60)  NOT NULL CONSTRAINT uq_fil_nom UNIQUE,
    niveau           VARCHAR2(10)  NOT NULL CONSTRAINT ck_fil_niveau CHECK (niveau IN ('Licence','Master')),
    duree_annees     NUMBER(1)     NOT NULL CONSTRAINT ck_fil_duree CHECK (duree_annees IN (2,3)),
    id_departement   NUMBER(4)     NOT NULL CONSTRAINT fk_fil_dep REFERENCES departements(id_departement)
);

CREATE TABLE enseignants (
    id_enseignant    NUMBER(6)     CONSTRAINT pk_enseignants PRIMARY KEY,
    nom              VARCHAR2(40)  NOT NULL,
    prenom           VARCHAR2(40)  NOT NULL,
    email            VARCHAR2(80)  NOT NULL CONSTRAINT uq_ens_email UNIQUE,
    grade            VARCHAR2(30)  NOT NULL,
    id_departement   NUMBER(4)     NOT NULL CONSTRAINT fk_ens_dep REFERENCES departements(id_departement),
    date_embauche    DATE          NOT NULL
);

CREATE TABLE salles (
    id_salle         NUMBER(4)     CONSTRAINT pk_salles PRIMARY KEY,
    nom_salle        VARCHAR2(10)  NOT NULL CONSTRAINT uq_sal_nom UNIQUE,
    batiment         VARCHAR2(20)  NOT NULL,
    capacite         NUMBER(4)     NOT NULL CONSTRAINT ck_sal_cap CHECK (capacite > 0),
    type_salle       VARCHAR2(20)  NOT NULL CONSTRAINT ck_sal_type CHECK (type_salle IN ('Amphi','Salle de cours','Laboratoire'))
);

CREATE TABLE etudiants (
    id_etudiant        NUMBER(6)     CONSTRAINT pk_etudiants PRIMARY KEY,
    cne                VARCHAR2(12)  NOT NULL CONSTRAINT uq_etu_cne UNIQUE,
    nom                VARCHAR2(40)  NOT NULL,
    prenom             VARCHAR2(40)  NOT NULL,
    sexe               CHAR(1)       NOT NULL CONSTRAINT ck_etu_sexe CHECK (sexe IN ('M','F')),
    date_naissance     DATE          NOT NULL,
    ville              VARCHAR2(40)  NOT NULL,
    email              VARCHAR2(80)  NOT NULL CONSTRAINT uq_etu_email UNIQUE,
    id_filiere         NUMBER(4)     NOT NULL CONSTRAINT fk_etu_fil REFERENCES filieres(id_filiere),
    annee_inscription  NUMBER(4)     NOT NULL
);

CREATE TABLE modules (
    id_module        NUMBER(4)     CONSTRAINT pk_modules PRIMARY KEY,
    nom_module       VARCHAR2(60)  NOT NULL,
    id_filiere       NUMBER(4)     NOT NULL CONSTRAINT fk_mod_fil REFERENCES filieres(id_filiere),
    semestre         NUMBER(1)     NOT NULL CONSTRAINT ck_mod_sem CHECK (semestre BETWEEN 1 AND 6),
    coefficient      NUMBER(3,1)   NOT NULL CONSTRAINT ck_mod_coef CHECK (coefficient > 0),
    volume_horaire   NUMBER(3)     NOT NULL CONSTRAINT ck_mod_vol CHECK (volume_horaire > 0),
    id_enseignant    NUMBER(6)     NOT NULL CONSTRAINT fk_mod_ens REFERENCES enseignants(id_enseignant)
);

CREATE TABLE seances (
    id_seance        NUMBER(6)     CONSTRAINT pk_seances PRIMARY KEY,
    id_module        NUMBER(4)     NOT NULL CONSTRAINT fk_sea_mod REFERENCES modules(id_module),
    id_salle         NUMBER(4)     NOT NULL CONSTRAINT fk_sea_sal REFERENCES salles(id_salle),
    id_enseignant    NUMBER(6)     NOT NULL CONSTRAINT fk_sea_ens REFERENCES enseignants(id_enseignant),
    jour             VARCHAR2(10)  NOT NULL CONSTRAINT ck_sea_jour CHECK (jour IN ('Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi')),
    heure_debut      VARCHAR2(5)   NOT NULL,
    heure_fin        VARCHAR2(5)   NOT NULL,
    type_seance      VARCHAR2(10)  NOT NULL CONSTRAINT ck_sea_type CHECK (type_seance IN ('Cours','TD')),
    CONSTRAINT uq_sea_salle   UNIQUE (id_salle, jour, heure_debut),
    CONSTRAINT uq_sea_ens     UNIQUE (id_enseignant, jour, heure_debut)
);

CREATE TABLE notes (
    id_note              NUMBER(8)     CONSTRAINT pk_notes PRIMARY KEY,
    id_etudiant          NUMBER(6)     NOT NULL CONSTRAINT fk_not_etu REFERENCES etudiants(id_etudiant),
    id_module            NUMBER(4)     NOT NULL CONSTRAINT fk_not_mod REFERENCES modules(id_module),
    session_exam         VARCHAR2(10)  NOT NULL CONSTRAINT ck_not_session CHECK (session_exam IN ('Normale','Rattrapage')),
    note                 NUMBER(4,2)   NOT NULL CONSTRAINT ck_not_note CHECK (note BETWEEN 0 AND 20),
    annee_universitaire  VARCHAR2(9)   NOT NULL,
    CONSTRAINT uq_not_etu_mod_ses UNIQUE (id_etudiant, id_module, session_exam)
);

CREATE TABLE absences (
    id_absence    NUMBER(8)    CONSTRAINT pk_absences PRIMARY KEY,
    id_etudiant   NUMBER(6)    NOT NULL CONSTRAINT fk_abs_etu REFERENCES etudiants(id_etudiant),
    id_seance     NUMBER(6)    NOT NULL CONSTRAINT fk_abs_sea REFERENCES seances(id_seance),
    date_absence  DATE         NOT NULL,
    justifiee     VARCHAR2(3)  NOT NULL CONSTRAINT ck_abs_just CHECK (justifiee IN ('Oui','Non'))
);

-- Index sur les cles etrangeres (Oracle ne les cree pas automatiquement)
CREATE INDEX idx_fil_dep    ON filieres(id_departement);
CREATE INDEX idx_ens_dep    ON enseignants(id_departement);
CREATE INDEX idx_etu_fil    ON etudiants(id_filiere);
CREATE INDEX idx_mod_fil    ON modules(id_filiere);
CREATE INDEX idx_mod_ens    ON modules(id_enseignant);
CREATE INDEX idx_sea_mod    ON seances(id_module);
CREATE INDEX idx_not_mod    ON notes(id_module);
CREATE INDEX idx_abs_etu    ON absences(id_etudiant);
CREATE INDEX idx_abs_sea    ON absences(id_seance);

